<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Company; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class CompanyController extends Controller { public function index(Request $request){$this->authorize('platformView',Company::class);$companies=Company::query()->when($request->search,fn($q,$s)=>$q->where('name','like',"%{$s}%"))->latest()->paginate(15)->withQueryString();return view('admin.companies.index',compact('companies'));} public function create(){$this->authorize('platformView',Company::class);return view('admin.companies.create');} public function store(Request $request){$this->authorize('platformView',Company::class);$data=$request->validate(['name'=>['required','string','max:150'],'email'=>['nullable','email'],'status'=>['required',Rule::in(['active','inactive'])]]);$data['slug']=Str::slug($data['name']).'-'.Str::lower(Str::random(6));Company::create($data);return redirect()->route('admin.companies.index')->with('success','Company created.');} public function edit(Company $company){$this->authorize('platformView',Company::class);return view('admin.companies.edit',compact('company'));} public function update(Request $request,Company $company){$this->authorize('platformView',Company::class);$data=$request->validate(['name'=>['required','string','max:150'],'email'=>['nullable','email'],'status'=>['required',Rule::in(['active','inactive'])]]);$company->update($data);return redirect()->route('admin.companies.index')->with('success','Company updated.');} }
